namespace Slic3r::GUI::JusPrin::PrinterSetup {

namespace {

// The same pacing the shell gives the docked panel's host.
constexpr int kPumpIntervalMs = 33;
constexpr int kPumpTimerId    = wxID_HIGHEST + 1803;

// How often a torn-down web view that could not be destroyed yet is looked at
// again.
constexpr int kReleaseRetryMs = 50;
constexpr int kReleaseTimerId = wxID_HIGHEST + 1804;

} // namespace

PrinterPanel::PrinterPanel(wxWindow*              parent,
                           const ShellTheme&      theme,
                           bool                   dark,
                           Workspace::IWorkspace& workspace,
                           Plater&                plater,
                           Workspace::SpoolStore* spools,
                           Callbacks              callbacks)
    : wxPanel(parent, wxID_ANY)
    , m_theme(theme)
    , m_dark(dark)
    , m_workspace(workspace)
    , m_callbacks(std::move(callbacks))
    , m_backend(std::make_unique<OrcaPrinterBackend>(plater, PrinterCatalog::load(Slic3r::resources_dir()), spools))
    // The cast is made here, inside the class, because this panel keeps its
    // conversation-host side private.
    , m_conversation(new PrinterConversation(*m_backend, static_cast<IConversationHost&>(*this)))
    , m_pump(this, kPumpTimerId)
    , m_release_timer(this, kReleaseTimerId)
{
    SetSizer(new wxBoxSizer(wxVERTICAL));
    Bind(wxEVT_TIMER, &PrinterPanel::on_pump, this, kPumpTimerId);
    Bind(wxEVT_TIMER, &PrinterPanel::on_release_retired, this, kReleaseTimerId);
}

PrinterPanel::~PrinterPanel()
{
    m_pump.Stop();
    m_release_timer.Stop();
}

void PrinterPanel::build_runtime()
{
    // Its own document, never the project's: a printer conversation is not
    // part of the project it happens to be opened over, and is gone when the
    // panel closes.
    Agent::ProjectPersistence::Config storage;
    storage.in_memory = true;
    m_persistence     = std::make_unique<Agent::ProjectPersistence>(m_workspace, std::move(storage));

    // Its own agent service too: one turn may be in flight per service, and
    // the docked panel's belongs to the project's conversation.
    Agent::AgentRuntime runtime = Agent::load_agent_runtime(wxGetApp().app_config);
    m_web_view = std::make_unique<AgentWebView>(this, m_theme, m_workspace, *m_persistence, runtime.availability,
                                                std::move(runtime.service), runtime.setup, AgentPageMode::PrinterPanel);
    m_web_view->apply_appearance(m_dark);
    m_web_view->SetName(_L("Printer conversation"));
    GetSizer()->Add(m_web_view.get(), 1, wxEXPAND);
    Layout();

    Agent::AgentHost& host = m_web_view->host();
    host.set_session_profile(m_conversation->profile());
    host.set_session_state_provider([this] { return m_conversation->state_json(); });
    host.set_page_message_handler([this](const std::string& type, const nlohmann::json& payload) {
        return m_conversation->handle_page_message(type, payload);
    });
    host.set_session_tool_executor([this](Agent::ToolHandler handler, const Agent::ToolActivity& activity) {
        return m_conversation->execute_tool(handler, activity);
    });
    host.set_session_tool_preflight([this](Agent::ToolHandler handler, Agent::ToolActivity& activity) {
        return m_conversation->preflight_tool(handler, activity);
    });
    host.set_session_tool_output([this](const Agent::ToolActivity& activity) { return m_conversation->tool_output(activity); });
    // Setting the agent up in here is the same act as setting it up anywhere
    // else; the rest of the shell has to look again afterwards.
    host.set_setup_completed_listener([this] {
        if (m_callbacks.agent_configured)
            m_callbacks.agent_configured();
        if (m_web_view)
            m_web_view->host().set_session_profile(m_conversation->profile());
    });
    m_pump.Start(kPumpIntervalMs);
}

void PrinterPanel::tear_down_runtime()
{
    m_pump.Stop();
    if (!m_web_view)
        return;
    GetSizer()->Detach(m_web_view.get());

    // On macOS a new web view installs its script message handler from a
    // CallAfter (WebView::CreateWebView), and wx waits for WebKit's reply to
    // that install inside a nested event loop, with the app's
    // is_adding_script_handler() flag set until it returns. A view destroyed
    // during that wait is called back by WebKit after it is gone, and the app
    // crashes. So while any view is mid-install, this runtime is hidden, cut
    // off from the session, and destroyed once the install is over -- the same
    // wait GUI_App::run_wizard makes.
    if (wxGetApp().is_adding_script_handler()) {
        m_web_view->Hide();
        Agent::AgentHost& host = m_web_view->host();
        host.set_session_state_provider({});
        host.set_page_message_handler({});
        host.set_session_tool_executor({});
        host.set_setup_completed_listener({});
        m_retired.push_back({std::move(m_persistence), std::move(m_web_view)});
        m_release_timer.StartOnce(kReleaseRetryMs);
        return;
    }

    // Deleted here rather than handed to wx: the host inside it holds this
    // session's document by reference, and that document goes next. Both
    // callers are outside the view's own event handling -- open() comes from
    // the shell, close() from a CallAfter -- which is what makes this safe.
    m_web_view.reset();
    m_persistence.reset();
}

void PrinterPanel::on_release_retired(wxTimerEvent&)
{
    if (wxGetApp().is_adding_script_handler()) {
        m_release_timer.StartOnce(kReleaseRetryMs);
        return;
    }
    m_retired.clear();
}

void PrinterPanel::open(ConversationMode mode, const std::string& printer_name)
{
    // Every opening is a new session: no history carries over, so the runtime
    // that held the last one goes first.
    tear_down_runtime();
    m_conversation->start(mode, printer_name);
    // The page writes the opening line and asks for it to be posted once it
    // has loaded (printer_opening).
    build_runtime();
    Show();
}

void PrinterPanel::close(const PinnedFacts* added)
{
    Hide();
    // Copied now: tear_down_runtime destroys the conversation that owns the
    // facts `added` points at, and that runs before the deferred callback
    // below reads them.
    const std::optional<PinnedFacts> pending = added != nullptr ? std::optional<PinnedFacts>(*added) : std::nullopt;
    // The runtime is destroyed from the page's own message handler, so it
    // cannot be torn down inside a call its own host is still on the stack
    // for -- the trap the add-printer dialog documented.
    CallAfter([this, pending] {
        tear_down_runtime();
        if (m_callbacks.closed)
            m_callbacks.closed(pending ? &*pending : nullptr);
    });
}

Agent::AgentHost* PrinterPanel::host() { return m_web_view ? &m_web_view->host() : nullptr; }

void PrinterPanel::apply_appearance(bool dark)
{
    m_dark = dark;
    if (m_web_view)
        m_web_view->apply_appearance(dark);
}

void PrinterPanel::on_pump(wxTimerEvent&)
{
    if (!m_web_view)
        return;
    Agent::AgentHost& host = m_web_view->host();
    host.pump_stream();
    host.pump_tools();
    host.pump_setup();
}

// -- What the conversation asks of its panel ---------------------------------

std::string PrinterPanel::post_note(const std::string& text)
{
    return m_web_view ? m_web_view->host().post_note(text) : std::string();
}

std::string PrinterPanel::post_opening(const std::string& text)
{
    return m_web_view ? m_web_view->host().post_assistant_message(text) : std::string();
}

void PrinterPanel::start_turn()
{
    if (m_web_view)
        m_web_view->host().start_turn();
}

void PrinterPanel::session_changed()
{
    if (!m_web_view)
        return;
    // A change to the printer is also a change to what the model is told
    // about it.
    m_web_view->host().set_session_profile(m_conversation->profile());
    m_web_view->host().send_page_envelope(Agent::Protocol::kPrinterSession, m_conversation->state_json());
}

void PrinterPanel::profile_changed()
{
    if (m_web_view)
        m_web_view->host().set_session_profile(m_conversation->profile());
}

void PrinterPanel::close_panel(const PinnedFacts* added) { close(added); }

void PrinterPanel::printers_changed(const PinnedFacts* added)
{
    if (m_callbacks.printers_changed)
        m_callbacks.printers_changed(added);
}

} // namespace Slic3r::GUI::JusPrin::PrinterSetup
#include "PrinterConversation.hpp"

#include "slic3r/GUI/JusPrin/Support/Base64.hpp"

#include <algorithm>
#include <filesystem>
#include <fstream>
#include <sstream>

namespace Slic3r::GUI::JusPrin::PrinterSetup {

using nlohmann::json;
using Agent::ToolActivity;
using Agent::ToolError;
using Agent::ToolHandler;
using Agent::ToolExecutionCoordinator;

namespace {

// At most three candidates: more is a list to read rather than an answer.
constexpr std::size_t kMaximumCandidates = 3;

// The Add instructions carry every printer, about 28 KB; well above that is
// not a prompt the page meant to send.
constexpr std::size_t kInstructionsLimit = 256 * 1024;

// A note or the opening is a sentence or two; a page that sends more has a
// bug, and none of it reaches the thread.
constexpr std::size_t kNoteLimit = 2 * 1024;

// The note the page wrote for a tap, or empty when it sent none it may.
std::string page_note(const json& payload)
{
    const auto note = payload.find("note");
    if (note == payload.end() || !note->is_string())
        return {};
    const std::string text = note->get<std::string>();
    return text.size() <= kNoteLimit ? text : std::string();
}

std::string number_text(double value)
{
    std::ostringstream out;
    out.precision(2);
    out << std::fixed << value;
    std::string text = out.str();
    while (text.size() > 3 && text.back() == '0')
        text.pop_back();
    return text;
}

std::string nozzle_text(double nozzle) { return nozzle > 0. ? number_text(nozzle) + " mm" : std::string(); }

// The profile's own spelling of a nozzle size, as the variant is named:
// "0.4", "0.25", "1.0".
std::string variant_text(double nozzle) { return number_text(nozzle); }

// "a, b and c"
std::string listed(const std::vector<std::string>& items)
{
    std::string text;
    for (std::size_t i = 0; i < items.size(); ++i)
        text += (i == 0 ? "" : i + 1 == items.size() ? " and " : ", ") + items[i];
    return text;
}

// "0.2, 0.4, 0.6 and 0.8 mm"
std::string sizes_text(const std::vector<double>& nozzles)
{
    std::vector<std::string> sizes;
    for (double nozzle : nozzles)
        sizes.push_back(number_text(nozzle));
    return listed(sizes) + " mm";
}

// A nozzle of null or 0 is the model leaving it unsaid.
bool said_nozzle(const json& arguments)
{
    return arguments.contains("nozzle") && arguments["nozzle"].is_number() && arguments["nozzle"].get<double>() > 0.;
}

bool ships(const std::vector<double>& nozzles, double nozzle)
{
    return std::find(nozzles.begin(), nozzles.end(), nozzle) != nozzles.end();
}

std::string picture_data_url(const std::string& path)
{
    if (path.empty())
        return {};
    std::ifstream file(std::filesystem::u8path(path), std::ios::binary);
    if (!file.good())
        return {};
    std::ostringstream bytes;
    bytes << file.rdbuf();
    const std::string data = bytes.str();
    if (data.empty())
        return {};
    return "data:image/png;base64," + base64_encode(data);
}

json nullable(const std::string& text) { return text.empty() ? json(nullptr) : json(text); }

json spools_json(const std::vector<PrinterSpool>& spools)
{
    json list = json::array();
    for (const PrinterSpool& spool : spools) {
        json entry{{"name", spool.name}, {"material", spool.material}};
        if (!spool.colour.empty())
            entry["colour"] = spool.colour;
        list.push_back(std::move(entry));
    }
    return list;
}

std::vector<PrinterSpool> spools_of(const json& list)
{
    std::vector<PrinterSpool> spools;
    for (const json& spool : list)
        spools.push_back(PrinterSpool{spool.value("name", std::string()), spool.value("material", std::string()),
                                      spool.value("colour", std::string())});
    return spools;
}

bool same_spools(const std::vector<PrinterSpool>& lhs, const std::vector<PrinterSpool>& rhs)
{
    return std::equal(lhs.begin(), lhs.end(), rhs.begin(), rhs.end(), [](const PrinterSpool& a, const PrinterSpool& b) {
        return a.name == b.name && a.material == b.material && a.colour == b.colour;
    });
}

// "PLA Matte, PETG" or "none"
std::string spools_text(const std::vector<PrinterSpool>& spools)
{
    std::vector<std::string> names;
    for (const PrinterSpool& spool : spools)
        names.push_back(spool.name.empty() ? spool.material : spool.name);
    return names.empty() ? std::string("none") : listed(names);
}

std::vector<PrinterSpool> reported_spools(const DiscoveredPrinter& device)
{
    std::vector<PrinterSpool> spools;
    for (const DiscoveredPrinter::Spool& spool : device.spools)
        spools.push_back(PrinterSpool{spool.name, spool.material, spool.colour});
    return spools;
}

// A nozzle the printer reported is settled only when its model ships it.
bool reports_nozzle(const DiscoveredPrinter& device, const CatalogPrinter& printer)
{
    return device.nozzle_diameter > 0. && ships(printer.nozzles, device.nozzle_diameter);
}

} // namespace

PrinterConversation::PrinterConversation(IPrinterBackend& backend, IConversationHost& host)
    : m_backend(backend), m_host(host)
{}

std::vector<std::string> PrinterConversation::session_tools(ConversationMode mode)
{
    // One tool per mode. A Change session that could identify a printer
    // could also clear the card of the printer it is about.
    return {mode == ConversationMode::Add ? "printer_identify" : "printer_change"};
}

void PrinterConversation::start(ConversationMode mode, const std::string& printer_name)
{
    m_mode         = mode;
    m_printer_name = printer_name;
    m_printer      = {};
    m_proposal     = {};
    m_blocks       = json::array();
    m_next_block   = 1;
    m_stated_nozzle.clear();
    m_undo.reset();
    // A new session's page writes its instructions again.
    m_instructions.clear();
    m_network.clear();
    m_opened = false;

    m_facts = {};
    // A printer this app has not saved cannot be changed, and the header's
    // menu can name one: a system profile is selected until the person adds
    // a printer of their own. Adding one is what there is to do.
    if (m_mode == ConversationMode::Change) {
        const std::vector<SavedPrinter> saved = m_backend.saved_printers();
        if (std::none_of(saved.begin(), saved.end(),
                         [this](const SavedPrinter& printer) { return printer.name == m_printer_name; })) {
            m_mode = ConversationMode::Add;
            m_printer_name.clear();
        }
    }

    if (m_mode == ConversationMode::Change)
        read_saved_printer();
    else {
        refresh_network();
        // A photo is the fastest way in, and the printers already on the
        // network are the fastest of all. Both belong under the opening,
        // where the person is deciding what to say.
        m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""}, {"kind", "tip"}});
        if (!m_network.empty()) {
            json found = json::array();
            for (const DiscoveredPrinter& printer : m_network) {
                json entry{{"deviceId", printer.stable_id},
                           {"name", printer.name},
                           {"serial", printer.stable_id},
                           {"online", printer.connected}};
                // What "Use this" would put on the card, so the page can say
                // so to the model when it is tapped.
                if (const CatalogPrinter* model = model_of(printer)) {
                    const bool reported = reports_nozzle(printer, *model);
                    entry["match"] = json{{"name", model->display_name()},
                                          {"nozzle", reported ? printer.nozzle_diameter : assumed_nozzle(*model)},
                                          {"reported", reported}};
                }
                found.push_back(std::move(entry));
            }
            m_blocks.push_back(json{{"id", next_block_id()},
                                    {"seq", m_blocks.size() + 1},
                                    {"afterMessageId", ""},
                                    {"kind", "network"},
                                    {"printers", std::move(found)}});
        }
    }
    m_host.session_changed();
}

void PrinterConversation::post_opening(const std::string& text)
{
    // The first line is the page's to write and the app's to post, once: a
    // reloaded page asks again, and the thread already has it.
    if (m_opened || text.empty() || text.size() > kNoteLimit)
        return;
    m_opened                     = true;
    const std::string message_id = m_host.post_opening(text);
    for (json& entry : m_blocks)
        if (entry.value("afterMessageId", std::string()).empty())
            entry["afterMessageId"] = message_id;
    m_host.session_changed();
}

void PrinterConversation::read_saved_printer()
{
    for (const SavedPrinter& saved : m_backend.saved_printers())
        if (saved.name == m_printer_name)
            m_printer = saved;

    m_facts         = {};
    m_facts.printer = m_printer.name.empty() ? m_printer_name : m_printer.name;
    m_facts.nozzle  = m_printer.nozzle;
    // The plate a printer is set up with is a starting point rather than a
    // reading: it is the plate its profile ships with until a project says
    // otherwise.
    m_facts.plate            = m_printer.plate;
    m_facts.plate_provenance = "assumed";
    m_facts.ams              = m_printer.ams;
    m_facts.spools           = m_printer.spools;
"}

