const EM_DASH = '—';

function factClass(fact: FactText): string {
  if (!fact.value) return 'printer-fact-value printer-fact-empty';
  return `printer-fact-value printer-fact-${fact.provenance}`;
}

function factSuffix(fact: FactText): string {
  if (!fact.value) return '';
  if (fact.provenance === 'assumed') return ' · assumed';
  if (fact.provenance === 'changed') return ' · changed';
  return '';
}

function FactRow({ label, fact }: { label: string; fact: FactText }) {
  return (
    <div className="printer-fact">
      <span className="printer-fact-label">{label}</span>
      <span className={factClass(fact)}>
        {fact.swatch && <span className="printer-swatch" style={{ background: fact.swatch }} aria-hidden="true" />}
        {fact.value || EM_DASH}
        {factSuffix(fact)}
      </span>
    </div>
  );
}

// The four facts a printer is, in the order the panel always states them.
export const PrinterPinnedCard = memo(function PrinterPinnedCard({ session }: { session: PrinterSessionPayload }) {
  const facts = factTexts(session.facts);
  return (
    <section className="printer-pinned" aria-label={caption(session)}>
      <p className="printer-pinned-caption">{caption(session)}</p>
      <FactRow label="Printer" fact={facts.printer} />
      <FactRow label="Nozzle" fact={facts.nozzle} />
      <FactRow label="Plate" fact={facts.plate} />
      <FactRow label="Filament" fact={facts.filament} />
    </section>
  );
});

// The camera the panel shows wherever a photo is offered. Inline, like the
// composer's send arrow, because the icon set carries no camera yet.
export function CameraGlyph({ className }: { className: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
      <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z" />
      <circle cx="12" cy="13" r="4" />
    </svg>
  );
}

export type PrinterBlockAction = 'network_pick' | 'candidate_pick' | 'undo';

// A tap on a card: the card's id, and the note the model is told if it goes
// through.
export interface PrinterTap {
  blockId?: string;
  note?: string;
}

export interface PrinterBlockProps {
  block: PrinterBlock;
  onAction: (action: PrinterBlockAction, id: string, tap: PrinterTap) => void;
}

// One card in the thread, under the message it belongs to.
export const PrinterBlockView = memo(function PrinterBlockView({ block, onAction }: PrinterBlockProps) {
  if (block.kind === 'tip')
    return (
      <div className="printer-tip">
        <CameraGlyph className="printer-tip-icon" />
        <span>
          <b>Tip:</b> a photo is the fastest way. Use <b>Photo</b> below, or drop a picture of the printer, its nameplate or the box
          into this panel.
        </span>
      </div>
    );

  if (block.kind === 'network') {
    const found = (block.printers ?? []) as NetworkPrinterInfo[];
    return (
      <div className="printer-found">
        <p className="printer-found-caption">FOUND ON YOUR NETWORK</p>
        {found.map((printer) => (
          <div className="printer-row" key={printer.deviceId}>
            <span className={printer.online ? 'printer-dot printer-dot-online' : 'printer-dot'} aria-hidden="true" />
            <span className="printer-row-name">
              {printer.name}
              <small>{printer.serial}</small>
            </span>
            <button
              type="button"
              className="printer-quiet-button"
              onClick={() => onAction('network_pick', printer.deviceId, { note: networkNote(printer) })}
            >
              Use this
            </button>
          </div>
        ))}
      </div>
    );
  }

  if (block.kind === 'undo')
    return (
      <div className="printer-undo">
        <span>{undoText(block)}</span>
        <span aria-hidden="true"> · </span>
        <button type="button" className="printer-link-button" onClick={() => onAction('undo', block.id, { note: undoneNote(block) })}>
          Undo
        </button>
      </div>
    );

  const printers = (block.printers ?? []) as PrinterCardInfo[];
  // A card a newer answer replaced, or the person refused, stays in the
  // thread as a line, so the conversation still reads in order.
  if (block.collapsed)
    return <div className="printer-cards-collapsed">{printers.map((printer) => printer.name).join(' · ')}</div>;

  // One printer is an answer and gets the full card; two or three are a
  // question, and each carries the button that answers it.
  const compact = printers.length > 1;
  return (
    <div className={compact ? 'printer-cards printer-cards-compact' : 'printer-cards'}>
      {printers.map((printer) => (
        <div className="printer-card" key={printer.catalogId}>
          {printer.picture ? (
            <img className="printer-card-picture" src={printer.picture} alt="" />
          ) : (
            <span className="printer-card-picture printer-card-picture-empty" aria-hidden="true" />
          )}
          <span className="printer-card-name">
            {printer.name}
            {cardSubline(printer) && <small>{cardSubline(printer)}</small>}
          </span>
          {compact && (
            <button
              type="button"
              className="printer-quiet-button"
              onClick={() => onAction('candidate_pick', printer.catalogId, { blockId: block.id, note: chosenNote(printer) })}
            >
              This one
            </button>
          )}
        </div>
      ))}
    </div>
  );
});

// The code a Bambu printer shows under Settings > Network. It goes with Add
// to the app, which connects the printer; it is never part of the chat.
export function PrinterAccessCode({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  return (
    <input
      className="printer-access-code"
      type="text"
      autoComplete="off"
      spellCheck={false}
      maxLength={32}
      aria-label="Access code"
      placeholder="access code, optional"
      value={value}
      onChange={(event) => onChange(event.target.value)}
    />
  );
}

export interface ChipRowProps {
  canAdd: boolean;
  disabled: boolean;
  onAdd: () => void;
  onReject: () => void;
}

// What the person can do with the printer on the card. Both act natively;
// adding leads, because the tap is the approval.
export const PrinterChipRow = memo(function PrinterChipRow({ canAdd, disabled, onAdd, onReject }: ChipRowProps) {
  if (!canAdd) return null;
  return (
    <div className="printer-chips">
      <button type="button" className="printer-chip printer-chip-primary" disabled={disabled} onClick={onAdd}>
        {ADD_LABEL}
      </button>
      <button type="button" className="printer-chip printer-chip-plain" disabled={disabled} onClick={onReject}>
        {REJECT_LABEL}
      </button>
    </div>
  );
});

function SpoolList({ spools }: { spools: PrinterSpoolInfo[] }) {
  if (spools.length === 0) return <span className="printer-change-none">none</span>;
  return (
    <ul className="printer-change-spools">
      {spools.map((spool, index) => (
        <li key={`${spool.name}-${index}`}>
          {spool.colour && <span className="printer-swatch" style={{ background: spool.colour }} aria-hidden="true" />}
          {spool.name}
          {spool.material && spool.material !== spool.name && <small> {spool.material}</small>}
        </li>
      ))}
    </ul>
  );
}

// A change the model worked out from what the person said, stated in words
// before anything is saved: the card is where a misreading is caught.
export function PrinterChangeCard({
  activity,
  onDecision,
}: {
  activity: ToolActivityInfo;
  onDecision: (actionId: string, decision: 'approve' | 'reject') => void;
}) {
  const args = activity.arguments as { nozzle?: number; spools?: PrinterSpoolInfo[]; confirm?: PrinterChangeConfirm };
  const confirm = args.confirm;
  const printer = confirm?.printer ?? 'this printer';
  const nozzle = args.nozzle !== undefined && confirm?.before.nozzle !== undefined;
  const spools = args.spools !== undefined && confirm?.before.spools !== undefined;
  const keep = nozzle && !spools ? `Keep ${mm(confirm!.before.nozzle!)}` : 'Keep as it is';
  const set = nozzle && !spools ? `Set ${mm(args.nozzle!)}` : spools && !nozzle ? 'Set these spools' : 'Set both';

  return (
    <div className={`printer-change state-${activity.state}`} data-testid={`tool-${activity.actionId}`}>
      <div className="printer-change-title">{changeTitle(nozzle, spools)}</div>
      {nozzle && (
        <>
          <div className="printer-change-line">
            {mm(confirm!.before.nozzle!)} → <b>{mm(args.nozzle!)}</b> on {printer}
          </div>
          <div className="printer-change-note">Every project that uses this printer slices for {mm(args.nozzle!)}.</div>
        </>
      )}
      {spools && (
        <div className="printer-change-line printer-change-spool-diff">
          <div>
            <small>Now on {printer}</small>
            <SpoolList spools={confirm!.before.spools!} />
          </div>
          <span aria-hidden="true">→</span>
          <div>
            <small>After</small>
            <SpoolList spools={args.spools!} />
          </div>
        </div>
      )}
      {activity.state === 'pending' && (
        <div className="printer-change-actions">
          <button type="button" className="printer-chip printer-chip-plain" onClick={() => onDecision(activity.actionId, 'reject')}>
            {keep}
          </button>
          <button
            type="button"
            className="printer-chip printer-chip-primary"
            onClick={() => onDecision(activity.actionId, 'approve')}
          >
            {set}
          </button>
        </div>
      )}
      {activity.state === 'rejected' && <div className="printer-change-state">Kept as it was</div>}
      {(activity.state === 'approved' || activity.state === 'running') && <div className="printer-change-state">Saving…</div>}
      {activity.state === 'failed' && <div className="tool-error">{activity.error?.message ?? 'The change was not saved.'}</div>}
    </div>
  );
}
// Every word the printer panel shows the person, and the notes it records for
// the model after a tap. The app sends facts -- sizes, spools, which printer,
// what changed -- and the words are made here. The model's instructions are
// in printerInstructions.ts.

import type {
  NetworkPrinterInfo,
  PrinterBlock,
  PrinterCardInfo,
  PrinterFacts,
  PrinterSessionPayload,
  PrinterSpoolInfo,
} from './bridge/protocol';

// -- Numbers and lists --------------------------------------------------------

// "0.4", "0.25", "1.0": two decimals, trailing zeros dropped down to one, as
// the printer profiles spell nozzle sizes.
export function numberText(value: number): string {
  let text = value.toFixed(2);
  while (text.length > 3 && text.endsWith('0')) text = text.slice(0, -1);
  return text;
}

export function mm(value: number): string {
  return `${numberText(value)} mm`;
}

// "a, b and c"
export function listed(items: string[]): string {
  return items.map((item, index) => (index === 0 ? '' : index + 1 === items.length ? ' and ' : ', ') + item).join('');
}

// "0.2, 0.4, 0.6 and 0.8 mm"
export function sizesText(nozzles: number[]): string {
  return `${listed(nozzles.map(numberText))} mm`;
}

function spoolName(spool: PrinterSpoolInfo): string {
  return spool.name || spool.material;
}

// "PLA Matte and PETG", or "none"
function spoolsText(spools: PrinterSpoolInfo[]): string {
  return spools.length === 0 ? 'none' : listed(spools.map(spoolName));
}

// What a printer has loaded, as one line: "AMS lite · PLA Matte + 3".
export function spoolSummary(ams: string, spools: PrinterSpoolInfo[]): string {
  if (spools.length === 0) return ams;
  const first = spoolName(spools[0]) + (spools.length > 1 ? ` + ${spools.length - 1}` : '');
  return ams ? `${ams} · ${first}` : first;
}

// -- The panel's fixed words --------------------------------------------------

export function caption(session: PrinterSessionPayload): string {
  return session.mode === 'add' ? 'NEW PRINTER' : 'PRINTER';
}

// A likely answer, rather than a standing invitation.
export function placeholder(session: PrinterSessionPayload): string {
  return session.mode === 'add'
    ? 'e.g. "bambu a1 mini" or "not sure, the small one"'
    : 'e.g. "I put a 0.6 nozzle on it" or "loaded black PETG"';
}

export const ADD_LABEL = 'Add this printer';
export const REJECT_LABEL = 'Not this one';

// What stands in for a tool-only turn while it still has no words: which
// tool the mode's own instructions let the model call. Add's only tool
// looks through the printer list; Change's only tool works out and applies
// a change, so it does not name a list that mode never shows.
export function workingText(mode: PrinterSessionPayload['mode']): string {
  return mode === 'add' ? 'Looking through the printer list…' : 'Working on it…';
}

// The panel's own first line, which the model is shown as having said: the
// same promise every time the panel opens.
export function opening(session: PrinterSessionPayload): string {
  if (session.mode === 'change') {
    const name = session.context?.printer?.name || session.facts.printer.name || 'this printer';
    return `This is the ${name}. Tell me what changed on it, or ask anything about it: nozzle, plate, spools. A photo of the part works too.`;
  }
  return (
    "I'll add your printer so your projects slice for it. " +
    'What printer do you have? Say it any way: "bambu a1 mini", "the ender with the touchscreen", "not sure, the small one".'
  );
}

// -- The pinned card ----------------------------------------------------------

export interface FactText {
  value: string; // empty: nobody has said yet
  provenance: PrinterFacts['printer']['provenance'];
  swatch?: string;
}

export function factTexts(facts: PrinterFacts): { printer: FactText; nozzle: FactText; plate: FactText; filament: FactText } {
  const loaded = facts.filament.spools;
  return {
    printer: { value: facts.printer.name, provenance: facts.printer.provenance },
    nozzle: { value: facts.nozzle.size > 0 ? mm(facts.nozzle.size) : '', provenance: facts.nozzle.provenance },
    plate: { value: facts.plate.name, provenance: facts.plate.provenance },
    filament: {
      value: loaded.length > 0 || facts.filament.ams ? spoolSummary(facts.filament.ams, loaded) : facts.filament.preset,
      provenance: facts.filament.provenance,
      swatch: loaded[0]?.colour || undefined,
    },
  };
}

// -- The cards in the thread --------------------------------------------------

// Under a printer's name: what the printer reported, or its size.
export function cardSubline(card: PrinterCardInfo): string {
  const device = card.device;
  if (!device) return card.buildVolume;
  let text = `${mm(device.nozzle)} nozzle`;
  if (device.spools.length > 0) text += ` · ${spoolSummary(device.ams, device.spools)}`;
  if (device.reported) text += ' · read from the printer just now';
  return text;
}

// The undo row: "Nozzle set to 0.6 mm", "Spools updated", or both.
export function undoText(block: PrinterBlock): string {
  const parts: string[] = [];
  if (block.changed?.nozzle) parts.push(`Nozzle set to ${mm(block.changed.nozzle.after)}`);
  if (block.changed?.spools) parts.push(parts.length > 0 ? 'spools updated' : 'Spools updated');
  return parts.join(', ');
}

// The change card's title.
export function changeTitle(nozzle: boolean, spools: boolean): string {
  return nozzle && spools ? 'Change nozzle and spools' : nozzle ? 'Change nozzle' : 'Change spools';
}

// -- What the model is told after a tap ---------------------------------------
// Statements of what the person did, never instructions. The app posts them
// only when the tap goes through as described.

export function rejectedNote(name: string): string {
  return `The person said ${name} is not their printer.`;
}

export function chosenNote(card: PrinterCardInfo): string {
  const assumed = [`a ${mm(card.assumed.nozzle)} nozzle`];
  if (card.assumed.plate) assumed.push(`the ${card.assumed.plate}`);
  if (card.assumed.filament) assumed.push(card.assumed.filament);
  let text = `The person chose ${card.name}. Its card offers Add, assuming ${listed(assumed)}`;
  if (!card.assumed.plate) text += '; the profile names no plate';
  if (!card.assumed.filament) text += '; the profile names no filament';
  return `${text}.`;
}

// For a network printer the app matched to a model in the list.
export function networkNote(printer: NetworkPrinterInfo): string {
  const match = printer.match;
  if (!match) return '';
  const start = `The person chose the network printer ${printer.serial}, a ${match.name}`;
  return match.reported
    ? `${start} that reports a ${mm(match.nozzle)} nozzle.`
    : `${start}; it did not report its nozzle, so its card assumes ${mm(match.nozzle)}.`;
}

export function undoneNote(block: PrinterBlock): string {
  const back: string[] = [];
  if (block.changed?.nozzle) back.push(`the nozzle is ${mm(block.changed.nozzle.before)} again`);
  if (block.changed?.spools) back.push(`the spools are ${spoolsText(block.changed.spools.before)} again`);
  return `The person undid the change: ${listed(back)}.`;
}

export const ACCESS_CODE_NOTE = 'An access code was entered.';

