interface ProviderOption {
  id: string;
  label: string;
  placeholder: string;
  available: boolean;
}

export const PROVIDERS: ProviderOption[] = [
  { id: 'anthropic', label: 'Anthropic', placeholder: 'sk-ant-…', available: false },
  { id: 'openai', label: 'OpenAI', placeholder: 'sk-…', available: true },
