}

.composer textarea:focus {
  outline: none;
}

/* Full-pane states */
.pane-state {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  padding: 16px;
  gap: 16px;
  background: var(--surface-canvas);
}

.pane-state h1 {
  font: var(--font-section);
  margin: 0;
}

.pane-state p {
  margin: 0;
  font: var(--font-body);
  color: var(--text-secondary);
}

.pane-state details {
  font: var(--font-label);
  color: var(--text-secondary);
  max-width: 100%;
}

.pane-state pre {
  white-space: pre-wrap;
  overflow-wrap: break-word;
}

.pane-state .footnote {
  font: var(--font-metadata);
}

/* Dock header shown in place of the conversation chrome while no Agent
   service is configured; same row metrics as .chat-header. */
.agent-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-canvas);
}

.agent-header .agent-title {
  flex: 1;
  font: var(--font-body-bold);
}

.agent-header .agent-badge {
  flex: 0 0 auto;
  padding: 0 8px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-pill);
  color: var(--text-secondary);
  font: var(--font-metadata);
  letter-spacing: 0.04em;
}

/* Agent setup. The screens replace the dock body in place, so they reuse
   .pane-state's metrics and only add the card, the provider tabs, and the

.printer-header h1 {
  flex: 1;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font: var(--font-body-bold);
  color: var(--text-primary);
}

.printer-manual-link {
  border: none;
  background: none;
  padding: 0;
  cursor: pointer;
  font: var(--font-label);
  color: var(--action-primary);
}

.printer-manual-link:hover {
  color: var(--action-primary-hover);
}

.printer-pinned {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px 16px;
